import {communityPublic,communityPreview,communityVotes,voteCommunityCode,COMMUNITY_STORAGE} from './community-client.mjs';
import {effectiveCodeStatus,codeWorkingStatus,patchStatus,safeCommunityUrl} from './community-model.mjs';
const root=new URL('.',import.meta.url),kind=document.body.dataset.community,host=document.getElementById('community-entries'),status=document.getElementById('community-status');let rows=[],votes=[];
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
function link(text,url,cls='community-button secondary'){const a=el('a',text,cls);a.href=safeCommunityUrl(url);a.target='_blank';a.rel='noopener noreferrer';return a;}
function image(src,alt,cls){const img=el('img',undefined,cls);img.src=new URL(safeCommunityUrl(src,{image:true}),root);img.alt=alt;img.loading='lazy';return img;}
function date(v){return v?new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v+'T00:00:00Z')):'';}
function empty(title,copy){const box=el('div',undefined,'community-empty');box.append(el('h3',title),el('p',copy));return box;}
function codeCard(v,id){const tally=votes.find(r=>r.id===id)||{},state=codeWorkingStatus(v,tally),card=el('article',undefined,'community-code'),top=el('div',undefined,'community-item-heading'),code=el('strong',v.code,'redeem-code'),badge=el('span',state,'community-badge '+state.toLowerCase().replaceAll(' ','-')),copy=el('button','Copy code','community-button');copy.type='button';copy.disabled=false;copy.onclick=async()=>{try{await navigator.clipboard.writeText(v.code);copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy code',2000);}catch{status.textContent='Copy could not run. Select the code and copy it manually.';}};top.append(code,badge);const details=el('p',v.rewards),meta=el('p',undefined,'community-meta');meta.textContent=[v.expires_on?'Expires '+date(v.expires_on):'Expiry not announced',v.checked_on?'Last checked '+date(v.checked_on):'Not yet verified'].join(' · ');card.append(top,details,meta);if(v.note)card.append(el('p',v.note,'community-note'));const actions=el('div',undefined,'community-actions');for(const [value,label,count] of [[1,'Working',tally.likes||0],[-1,'Not working',tally.dislikes||0]]){const button=el('button',label+' '+count,'community-button secondary vote-button');button.type='button';button.setAttribute('aria-label',label+' '+v.code);button.setAttribute('aria-pressed',String(tally.mine===value));button.onclick=async()=>{button.disabled=true;try{await voteCommunityCode(id,tally.mine===value?0:value);votes=await communityVotes();render();}catch(error){status.textContent=error.message;button.disabled=false;}};actions.append(button);}actions.append(copy);if(v.source_url)actions.append(link('Source',v.source_url));card.append(actions);return card;}
function patchCard(v){const card=el('article',undefined,'community-patch'),top=el('div',undefined,'community-item-heading');top.append(el('span',date(v.released_on)+' · UTC','community-meta'),el('span',patchStatus(v),'community-badge'));if(v.version)top.append(el('span',v.version,'community-badge'));card.append(top,el('h3',v.title));if(v.summary)card.append(el('p',v.summary,'patch-summary'));card.append(link('Read official announcement',v.source_url,'community-button'));return card;}
function creatorCard(v,id){const card=el('article',undefined,'community-creator');card.id='creator-'+id;const intro=el('div',undefined,'creator-intro'),copy=el('div',undefined,'creator-copy');intro.append(image(v.avatar_url,v.name+' profile picture','creator-avatar'));if(v.featured)copy.append(el('span','Featured creator','community-badge'));copy.append(el('h3',v.name),el('p',v.description));const actions=el('div',undefined,'creator-actions'),codeButton=el('button','Copy creator code','community-button');codeButton.type='button';codeButton.disabled=!v.creator_code;codeButton.title=v.creator_code?'Copy '+v.creator_code:'Creator code has not been added yet';codeButton.onclick=async()=>{try{await navigator.clipboard.writeText(v.creator_code);codeButton.textContent='Copied';setTimeout(()=>codeButton.textContent='Copy creator code',2000);}catch{status.textContent='Copy could not run. Creator code: '+v.creator_code;}};actions.append(link('Watch '+v.name+' on YouTube',v.channel_url,'community-button youtube-link'),codeButton);copy.append(actions);intro.append(copy);card.append(intro);if(v.videos?.length){const section=el('div',undefined,'creator-video-section');section.append(el('h4','Selected Clash of Critters videos'));const grid=el('div',undefined,'creator-video-grid');for(const video of v.videos){const a=link('',video.url,'creator-video');if(video.thumbnail)a.append(image(video.thumbnail,'','creator-video-thumb'));const text=el('div',undefined,'creator-video-copy');if(video.topic)text.append(el('span',video.topic,'community-meta'));text.append(el('strong',video.title),el('span','Watch on YouTube','creator-video-action'));a.append(text);grid.append(a);}section.append(grid);card.append(section);}return card;}
function render(){host.replaceChildren();const search=(document.getElementById('community-search')?.value||'').trim().toLowerCase(),filter=document.getElementById('community-filter')?.value||'all';let items=rows.filter(r=>r.kind===kind);if(kind==='code')items=items.filter(r=>(filter==='all'||(filter==='expired'?codeWorkingStatus(r.content,votes.find(v=>v.id===r.id))==='Not working':codeWorkingStatus(r.content,votes.find(v=>v.id===r.id))==='Working'))&&(!search||[r.content.code,r.content.rewards].some(x=>String(x||'').toLowerCase().includes(search))));if(kind==='patch')items=items.filter(r=>!search||[r.content.title,r.content.version,r.content.summary].some(x=>String(x||'').toLowerCase().includes(search)));items.sort((a,b)=>kind==='creator'?Number(b.content.featured)-Number(a.content.featured):(b.content.released_on||b.content.checked_on||b.published_at||'').localeCompare(a.content.released_on||a.content.checked_on||a.published_at||''));for(const row of items)try{host.append(kind==='code'?codeCard(row.content,row.id):kind==='patch'?patchCard(row.content):creatorCard(row.content,row.id));}catch{status.textContent='An entry could not be displayed.';}if(!items.length)host.append(empty(search?'No results found':kind==='code'?'No codes added yet':kind==='patch'?'No patch notes added yet':'More creators coming soon',search?'Try another search or clear the filters.':kind==='code'?'New codes will appear here after they have been added and checked.':kind==='patch'?'Official announcements will appear here with a source link and release date.':'Community creators will be featured here.'));}
async function load(){try{rows=await communityPublic();status.textContent='';if(kind==='code')try{votes=await communityVotes();}catch(error){status.textContent=error.message;}render();}catch(error){status.textContent=error.message;host.replaceChildren(empty('Unable to load updates','Please try again shortly.'));}}
for(const id of ['community-search','community-filter'])document.getElementById(id)?.addEventListener(id==='community-search'?'input':'change',render);
if(communityPreview||new URL(location.href).searchParams.has('draft')){const banner=el('div',undefined,'community-preview-note');banner.append(el('span',new URL(location.href).searchParams.has('draft')?'Draft preview — not published':'Local preview'));const a=el('a','Manage entries');a.href=new URL(communityPreview?'./admin.html?preview=1&community=1':'./admin.html',root);banner.append(a);document.querySelector('.guide-shell').prepend(banner);if(communityPreview)for(const a of document.querySelectorAll('.community-nav a'))a.search='?preview=1';window.addEventListener('storage',e=>{if(e.key===COMMUNITY_STORAGE||e.key==='tatari-community-votes-preview-v1')load();});window.addEventListener('community-preview-changed',load);}
load();

if(kind==='patch')setInterval(render,60000);
